const calc=p=>{const media=p.compras.reduce((s,x)=>s+x[2],0)/p.compras.length;const sug=Math.max(0,Math.ceil(media*1.15-p.estoque));return{media:Math.round(media),sug,status:p.estoque===0?"Ruptura":p.estoque/media<.35?"Atenção":"Normal"}};
export default function Home(){const [aba,setAba]=useState("Visão geral"),[baseClientes,setBaseClientes]=useState(clientes),[cliente,setCliente]=useState(clientes[0]),[clienteAbertoId,setClienteAbertoId]=useState(null),[busca,setBusca]=useState(""),[visita,setVisita]=useState(false),[pedido,setPedido]=useState({}),[cadastro,setCadastro]=useState(false),[contagem,setContagem]=useState({}),[historicoVisitas,setHistoricoVisitas]=useState([]),[catalogoAberto,setCatalogoAberto]=useState(false),[buscaProduto,setBuscaProduto]=useState(""),[pedidosSalvos,setPedidosSalvos]=useState([]),[campanhas,setCampanhas]=useState(campanhasIniciais),[campanhaPedido,setCampanhaPedido]=useState(null),[sugVendedor,setSugVendedor]=useState({}),[motivoSug,setMotivoSug]=useState("Promoção"),[solicitacoes,setSolicitacoes]=useState([]),[novaCampanha,setNovaCampanha]=useState(false),[sugCampanhaAberta,setSugCampanhaAberta]=useState(false),[baseVendedores,setBaseVendedores]=useState(vendedores),[editVendedor,setEditVendedor]=useState(null),[novoVendedor,setNovoVendedor]=useState(false),[gestaoClientes,setGestaoClientes]=useState(false),[editClienteMeta,setEditClienteMeta]=useState(null),[clienteAtencao,setClienteAtencao]=useState(null),[historicoCliente,setHistoricoCliente]=useState(null),[abaAtencao,setAbaAtencao]=useState("Visão geral"),[periodoVisitas,setPeriodoVisitas]=useState("Hoje"),[perfil,setPerfil]=useState("vendedor"),[usuarioVendedorId,setUsuarioVendedorId]=useState(1),[novo,setNovo]=useState({nome:"",cidade:"",canal:"Supermercado",tipoCliente:"Supermercado",telefone:"",responsavel:""});
const clientesPermitidos=useMemo(()=>perfil==="gestor"?baseClientes:baseClientes.filter(c=>c.vendedorId===usuarioVendedorId),[baseClientes,perfil,usuarioVendedorId]);const lista=useMemo(()=>clientesPermitidos.filter(c=>(c.nome+" "+c.cidade).toLowerCase().includes(busca.toLowerCase())),[busca,clientesPermitidos]);const salvarCliente=e=>{e.preventDefault();if(!novo.nome||!novo.cidade)return;const c={id:Date.now(),vendedorId:baseVendedores[0]?.id||null,metaVenda:0,vendaRealizada:0,justificativa:"",acao:"",metaMixCliente:baseVendedores[0]?.metaMix||1,nome:novo.nome,cidade:novo.cidade,canal:novo.canal,dias:0,meta:0,produtos:[],telefone:novo.telefone,responsavel:novo.responsavel};setBaseClientes([...baseClientes,c]);setCliente(c);setNovo({nome:"",cidade:"",canal:"Supermercado",tipoCliente:"Supermercado",telefone:"",responsavel:""});setCadastro(false);};const sugestao=cliente.produtos.reduce((s,p)=>s+calc(p).sug,0);const qtdPedido=Object.values(pedido).reduce((s,n)=>s+(+n||0),0);
const implantarProduto=prod=>{if(cliente.produtos.some(p=>p.nome===prod.nome))return;const novoProd={nome:prod.nome,estoque:0,venda:0,compras:[]};const atualizado={...cliente,produtos:[...cliente.produtos,novoProd]};setCliente(atualizado);setBaseClientes(baseClientes.map(c=>c.id===cliente.id?atualizado:c));};const removerProduto=nome=>{const atualizado={...cliente,produtos:cliente.produtos.filter(p=>p.nome!==nome)};setCliente(atualizado);setBaseClientes(baseClientes.map(c=>c.id===cliente.id?atualizado:c));};const salvarContagem=()=>{if(!Object.keys(contagem).length)return;const agora=new Date().toLocaleDateString("pt-BR",{day:"2-digit",month:"2-digit"});setBaseClientes(baseClientes.map(c=>c.id!==cliente.id?c:{...c,dias:0,produtos:c.produtos.map(p=>contagem[p.nome]===undefined?p:{...p,estoque:+contagem[p.nome],compras:[[agora,+contagem[p.nome],p.venda],...p.compras].slice(0,3)})}));setCliente({...cliente,dias:0,produtos:cliente.produtos.map(p=>contagem[p.nome]===undefined?p:{...p,estoque:+contagem[p.nome],compras:[[agora,+contagem[p.nome],p.venda],...p.compras].slice(0,3)})});setHistoricoVisitas([{cliente:cliente.nome,data:new Date().toLocaleDateString("pt-BR"),itens:Object.keys(contagem).length},...historicoVisitas]);setContagem({});setVisita(false);};const campanhaElegivel=c=>{const hoje=new Date().toISOString().slice(0,10);const periodo=(!c.inicio||hoje>=c.inicio)&&(!c.fim||hoje<=c.fim);const publico=c.publicoTipo==="Todos"||(c.publicoTipo==="Cliente"&&String(c.publicoId)===String(cliente.id))||(c.publicoTipo==="Vendedor"&&String(c.publicoId)===String(cliente.vendedorId));return periodo&&publico};const confirmarPedido=()=>{if(!qtdPedido)return;const itens=cliente.produtos.map(p=>({nome:p.nome,sistema:calc(p).sug,vendedor:+(sugVendedor[p.nome]||calc(p).sug),pedido:+(pedido[p.nome]||0)})).filter(x=>x.pedido>0);const campanhaCumprida=c=>{if(c.status!=="Ativa"||!campanhaElegivel(c))return false;if(c.regraTipo==="Quantidade total")return qtdPedido>=(c.minimo||0);if(c.regraTipo==="Produto específico")return (itens.find(i=>i.nome===c.produto)?.pedido||0)>=(c.minimo||0);if(c.regraTipo==="Mix de produtos")return itens.filter(i=>i.pedido>0).length>=(c.mixMinimo||0);if(c.regraTipo==="Quantidade + mix")return qtdPedido>=(c.minimo||0)&&itens.filter(i=>i.pedido>0).length>=(c.mixMinimo||0);return false};const campanhaAuto=campanhas.find(c=>campanhaCumprida(c));setPedidosSalvos([{id:Date.now(),numero:"PED-"+String(Date.now()).slice(-6),cliente:cliente.nome,data:new Date().toLocaleDateString("pt-BR"),itens,total:qtdPedido,status:"Preparado",campanha:campanhaAuto?.nome||null,beneficio:campanhaAuto?.brinde||null,motivo:motivoSug},...pedidosSalvos]);setPedido({});setSugVendedor({});setCampanhaPedido(null);};const enviarFaturamento=id=>setPedidosSalvos(pedidosSalvos.map(p=>p.id===id?{...p,status:"Enviado ao faturamento"}:p));const solicitarAcao=()=>setSugCampanhaAberta(true);const setSugestao=()=>setPedido(Object.fromEntries(cliente.produtos.map(p=>[p.nome,calc(p).sug])));
const mixAtual=cliente.produtos.length;const vendedorAtual=baseVendedores.find(v=>v.id===usuarioVendedorId);const metaMixAtual=cliente.metaMixCliente||vendedorAtual?.metaMix||1;const mixPct=Math.min(100,Math.round(mixAtual/metaMixAtual*100));
const Dashboard=()=> <><section className="sellerMix"><div><small>META DE MIX DO CLIENTE</small><h3>{cliente.nome}</h3><p>{mixAtual} de {metaMixAtual} produtos implantados · Meta de venda: {cliente.metaVenda||0} un.</p></div><div className="mixScore"><b>{mixPct}%</b><span>do mix atingido</span></div><div className="mixBar"><i style={{width:mixPct+"%"}}/></div>{mixPct<100&&<button onClick={()=>setCatalogoAberto(true)}>Implantar {metaMixAtual-mixAtual} {metaMixAtual-mixAtual===1?"item":"itens"} para atingir a meta</button>}</section><section className="kpis"><article><span>Clientes da rota</span><b>{clientesPermitidos.length}</b><small>carteira disponível</small></article><article><span>Meta do mês</span><b>78%</b><small>alvo +12%</small></article><article><span>Rupturas</span><b>{cliente.produtos.filter(p=>calc(p).status==="Ruptura").length}</b><small>no cliente atual</small></article><article><span>Reposição sugerida</span><b>{sugestao}</b><small>unidades</small></article></section><ClienteDetalhe/></>;
const ClienteDetalhe=()=>{const clienteAberto=baseClientes.find(x=>x.id===clienteAbertoId)||null;const statusCliente=c=>{const pct=c.metaVenda?Math.round((c.vendaRealizada||0)/c.metaVenda*100):0;if((c.vendaRealizada||0)===0)return {tipo:"semVenda",texto:"Sem venda"};if(pct<80)return {tipo:"abaixo",texto:"Abaixo da meta"};if(c.dias>=7)return {tipo:"atrasado",texto:"Atendimento atrasado"};return {tipo:"ok",texto:"Em dia"}};const ultimos=c=>{const mov=c.produtos.flatMap(p=>p.compras.map(h=>({data:h[0],produto:p.nome,estoque:h[1],venda:h[2]})));return mov.slice(0,6)};if(!clienteAberto)return <section className="clientListOnly"><div className="title"><div><small>MINHA CARTEIRA</small><h2>Clientes</h2><p>Selecione um cliente para ver histórico e iniciar atendimento.</p></div><button className="primary" onClick={()=>setCadastro(true)}>+ Novo cliente</button></div><div className="clientSearch"><input placeholder="Buscar por cliente, cidade ou tipo..." value={busca} onChange={e=>setBusca(e.target.value)}/></div><div className="customerDirectory">{lista.map(c=>{const st=statusCliente(c),pct=c.metaVenda?Math.round((c.vendaRealizada||0)/c.metaVenda*100):0;return <button key={c.id} className={"customerLine "+st.tipo} onClick={()=>{setCliente(c);setClienteAbertoId(c.id);setPedido({})}}><div className="customerAvatar">{c.nome.slice(0,2).toUpperCase()}</div><div className="customerName"><strong>{c.nome}</strong><small>{c.cidade} · {c.tipoCliente||c.canal||"Sem tipo"}</small></div><div className="customerMeta"><span>Meta</span><b>{pct}%</b></div><div className="customerVisit"><span>Último atendimento</span><b>há {c.dias} dias</b></div><em>{st.texto}</em><span className="chev">›</span></button>})}</div></section>;const c=clienteAberto,st=statusCliente(c),pct=c.metaVenda?Math.round((c.vendaRealizada||0)/c.metaVenda*100):0;return <section className="clientHistoryPage"><button className="backClients" onClick={()=>{setClienteAbertoId(null);setVisita(false)}}>‹ Voltar para clientes</button><div className={"clientHistoryHero "+st.tipo}><div><small>CLIENTE</small><h2>{c.nome}</h2><p>{c.cidade} · {c.tipoCliente||c.canal||"Sem tipo"}</p></div><div className="clientHeroActions"><span>{st.texto}</span><button className="primary" onClick={()=>{setCliente(c);setVisita(true)}}>{visita?"Atendimento iniciado":"Iniciar atendimento"}</button></div></div><div className="clientHistoryKpis"><article><span>Venda / meta</span><b>{c.vendaRealizada||0} / {c.metaVenda||0}</b><small>{pct}% atingido</small></article><article><span>Mix</span><b>{c.produtos.length} / {c.metaMixCliente||0}</b><small>produtos implantados</small></article><article><span>Último atendimento</span><b>{c.dias} dias</b><small>desde a última visita</small></article><article><span>Rupturas</span><b>{c.produtos.filter(p=>calc(p).status==="Ruptura").length}</b><small>itens sem estoque</small></article></div><div className="historyLayout"><article className="historyCard"><div className="goalTitle"><div><small>HISTÓRICO DO CLIENTE</small><h3>Últimos 6 atendimentos / vendas</h3></div><button className="historyLink" onClick={()=>setHistoricoCliente(c)}>Ver histórico completo</button></div><div className="lastSix">{ultimos(c).length?ultimos(c).map((h,i)=><div key={i}><span className="timelineDot"/><div><strong>{h.data}</strong><small>{h.produto}</small></div><span>Estoque <b>{h.estoque}</b></span><span>Venda <b>{h.venda}</b></span></div>):<div className="emptyHistory">Nenhum histórico registrado para este cliente.</div>}</div><div className="historySummary"><span><b>{historicoVisitas.filter(v=>v.cliente===c.nome).length}</b> visitas registradas</span><span><b>{c.produtos.reduce((n,p)=>n+p.compras.length,0)}</b> movimentações</span><span><b>{c.produtos.length}</b> produtos acompanhados</span></div></article><article className="historyCard"><small>SITUAÇÃO COMERCIAL</small><h3>Meta e atendimento</h3><div className="historyProgress"><div><span>Meta de venda</span><b>{pct}%</b></div><i><em style={{width:Math.min(100,pct)+"%"}}/></i></div><div className="historyNotes"><span><b>{Math.max(0,(c.metaVenda||0)-(c.vendaRealizada||0))}</b> unidades para a meta</span><span><b>{Math.max(0,(c.metaMixCliente||0)-c.produtos.length)}</b> produtos para meta de mix</span><span><b>{c.dias}</b> dias desde atendimento</span></div></article></div>{visita&&<div className="visitWork"><div className="title"><div><small>ATENDIMENTO EM ANDAMENTO</small><h3>Contagem de estoque</h3></div><button className="primary" onClick={()=>{salvarContagem();setClienteAbertoId(cliente.id)}}>Salvar atendimento</button></div><div className="products">{c.produtos.map(p=>{const x=calc(p);return <article className="product" key={p.nome}><div className="productHead"><div><h3>{p.nome}</h3><span className={"status "+x.status.toLowerCase()}>{x.status}</span></div><div className="numbers"><div><small>Estoque</small><input className="stockInput" type="number" min="0" value={contagem[p.nome]??p.estoque} onChange={e=>setContagem({...contagem,[p.nome]:e.target.value})}/></div><div><small>Média</small><b>{x.media}</b></div><div><small>Sugestão</small><b>{x.sug}</b></div></div></div></article>})}</div></div>}</section>};
const Visitas=()=>{const hoje=new Date().toLocaleDateString("pt-BR");const minhasVisitas=historicoVisitas.filter(v=>clientesPermitidos.some(c=>c.nome===v.cliente));const diasPeriodo=periodoVisitas==="Hoje"?1:periodoVisitas==="Semana"?7:30;const visitasPeriodo=periodoVisitas==="Hoje"?minhasVisitas.filter(v=>v.data===hoje):minhasVisitas.slice(0,diasPeriodo);const fator=periodoVisitas==="Hoje"?0.05:periodoVisitas==="Semana"?0.25:1;const clientesCriticos=clientesPermitidos.map(c=>{const metaPeriodo=Math.max(1,Math.round((c.metaVenda||0)*fator));const vendaPeriodo=Math.round((c.vendaRealizada||0)*fator);const pct=metaPeriodo?Math.round(vendaPeriodo/metaPeriodo*100):0;const rupturas=c.produtos.filter(p=>calc(p).status==="Ruptura").length;const mixPct=Math.min(100,Math.round(c.produtos.length/(c.metaMixCliente||1)*100));const prioridade=rupturas>0||pct<80||c.dias>=7;const score=(rupturas*40)+(pct<80?(80-pct):0)+(c.dias>=7?Math.min(30,c.dias):0)+(mixPct<70?15:0);const motivo=rupturas>0?"Ruptura":pct<80?"Venda abaixo da meta":c.dias>=7?"Visita atrasada":mixPct<70?"Mix baixo":"Em dia";return {...c,pct,rupturas,mixPct,prioridade,metaPeriodo,vendaPeriodo,score,motivo}}).sort((x,y)=>y.score-x.score);const vendaTotal=clientesCriticos.reduce((n,c)=>n+c.vendaPeriodo,0),metaTotal=clientesCriticos.reduce((n,c)=>n+c.metaPeriodo,0);return <section className="visitDashboard"><div className="title visitTitle"><div><small>MINHA ATIVIDADE COMERCIAL</small><h2>Visitas e vendas</h2><p>Prioridades da sua carteira.</p></div><button className="primary" onClick={()=>{setAba("Clientes");setVisita(true)}}>+ Nova visita</button></div><div className="visitPeriod">{["Hoje","Semana","Mês"].map(p=><button type="button" key={p} className={periodoVisitas===p?"active":""} onClick={()=>setPeriodoVisitas(p)}>{p}</button>)}</div><div className="visitSummary"><article><span>Visitas</span><b>{visitasPeriodo.length}</b><small>{periodoVisitas.toLowerCase()}</small></article><article><span>Vendas / meta</span><b>{metaTotal?Math.round(vendaTotal/metaTotal*100):0}%</b><small>{vendaTotal} / {metaTotal} un.</small></article><article><span>A atender</span><b>{clientesCriticos.filter(c=>c.prioridade).length}</b><small>prioridades</small></article><article><span>Rupturas</span><b>{clientesCriticos.reduce((n,c)=>n+c.rupturas,0)}</b><small>itens</small></article></div><div className="sellerQuick"><button onClick={()=>setAba("Clientes")}><b>⌕</b><span>Buscar cliente</span></button><button onClick={()=>{const c=clientesCriticos.find(x=>x.prioridade);if(c){setCliente(c);setAba("Clientes")}}}><b>!</b><span>Próxima prioridade</span></button><button onClick={()=>setAba("Pedidos")}><b>▤</b><span>Pedidos</span></button></div><div className="visitColumns"><section className="panel"><h3>Próximos clientes</h3><p className="panelIntro">Ordenados por necessidade de atendimento.</p>{clientesCriticos.map(c=><article className={"routePriority "+(c.prioridade?"critical":"")} key={c.id}><div className="routeMain"><strong>{c.nome}</strong><small>{c.cidade} · {c.tipoCliente||c.canal||"Sem tipo"} · há {c.dias} dias</small><em className="reasonTag">{c.motivo}</em><div className="mobileMetrics"><span>Venda <b>{c.pct}%</b></span><span>Mix <b>{c.mixPct}%</b></span><span>Rupt. <b>{c.rupturas}</b></span></div></div><div className="desktopMetric"><span>Venda</span><b>{c.pct}%</b></div><div className="desktopMetric"><span>Mix</span><b>{c.mixPct}%</b></div><div className="desktopMetric"><span>Rupturas</span><b>{c.rupturas}</b></div><button onClick={()=>{setCliente(c);setAba("Clientes")}}>{c.prioridade?"Atender":"Abrir"}</button></article>)}</section><section className="panel"><h3>Visitas realizadas</h3>{visitasPeriodo.length?visitasPeriodo.slice(0,8).map((v,i)=><article className="visitDone" key={i}><div><strong>{v.cliente}</strong><small>{v.data}</small></div><span>{v.itens} produtos</span><b>Concluída</b></article>):<div className="empty">Nenhuma visita neste período.</div>}</section></div></section>};
const Pedidos=()=> <section className="panel order"><div className="title"><div><small>PEDIDO E NEGOCIAÇÃO</small><h2>{cliente.nome}</h2><p>Compare sistema, sugestão comercial e quantidade confirmada pelo comprador.</p></div><button className="secondary" onClick={setSugestao}>Aplicar sistema</button></div><div className="campaignStrip autoCampaign"><strong>Campanhas automáticas</strong><small>O sistema aplica o benefício sozinho quando o pedido atingir a regra.</small>{campanhas.filter(c=>c.status==="Ativa"&&campanhaElegivel(c)).map(c=>{const itensAgora=cliente.produtos.map(p=>({nome:p.nome,pedido:+(pedido[p.nome]||0)}));const ok=c.regraTipo==="Quantidade total"?qtdPedido>=c.minimo:c.regraTipo==="Produto específico"?(itensAgora.find(i=>i.nome===c.produto)?.pedido||0)>=c.minimo:c.regraTipo==="Mix de produtos"?itensAgora.filter(i=>i.pedido>0).length>=c.mixMinimo:qtdPedido>=c.minimo&&itensAgora.filter(i=>i.pedido>0).length>=c.mixMinimo;return <span className={ok?"campaignHit":"campaignPending"} key={c.id}>{c.nome}: {c.regraTipo==="Produto específico"?c.minimo+" "+c.produto:c.regraTipo==="Mix de produtos"?c.mixMinimo+" produtos":c.regraTipo==="Quantidade + mix"?c.minimo+" un. + "+c.mixMinimo+" produtos":c.minimo+" un."} → {c.brinde} {ok?"✓ Campanha atingida":""}</span>})}</div>{cliente.produtos.map(p=>{const x=calc(p);return <div className="orderRow orderAdvanced" key={p.nome}><div><strong>{p.nome}</strong><small>Estoque {p.estoque} · média {x.media}</small></div><label><span>Sistema</span><b>{x.sug}</b></label><label><span>Vendedor</span><input type="number" min="0" value={sugVendedor[p.nome]??x.sug} onChange={e=>setSugVendedor({...sugVendedor,[p.nome]:e.target.value})}/></label><label><span>Pedido</span><input type="number" min="0" value={pedido[p.nome]??""} placeholder={sugVendedor[p.nome]??x.sug} onChange={e=>setPedido({...pedido,[p.nome]:e.target.value})}/></label></div>})}<div className="sellerReason"><label>Motivo da sugestão do vendedor<select value={motivoSug} onChange={e=>setMotivoSug(e.target.value)}><option>Promoção</option><option>Lançamento</option><option>Aumento de mix</option><option>Ponto extra</option><option>Negociação especial</option><option>Outro</option></select></label><button className="secondary" onClick={solicitarAcao}>Sugerir campanha especial ao gestor</button></div><div className="orderTotal"><span>Total confirmado</span><b>{qtdPedido} unidades</b><button disabled={!qtdPedido} onClick={confirmarPedido}>Preparar pedido</button></div>{pedidosSalvos.length>0&&<div className="savedOrders"><h3>Pedidos preparados</h3>{pedidosSalvos.map(p=><article key={p.id}><div><strong>{p.numero} · {p.cliente}</strong><small>{p.data} · {p.itens.length} itens {p.campanha?"· "+p.campanha:""}</small></div><b>{p.total} un.</b><span>{p.status}</span>{p.status==="Preparado"&&<button className="billingBtn" onClick={()=>enviarFaturamento(p.id)}>Enviar faturamento</button>}</article>)}</div>}</section>;
const Gestor=()=>{const [vendSel,setVendSel]=useState(baseVendedores[0]||null);const [territorio,setTerritorio]=useState("Todos");const totalRupturas=baseClientes.reduce((n,c)=>n+c.produtos.filter(p=>calc(p).status==="Ruptura").length,0);const totalMix=baseClientes.reduce((n,c)=>n+c.produtos.length,0);return <section className="manager"><div className="managerHero"><div><small>VISÃO GERENCIAL</small><h2>Equipe comercial</h2><p>Metas, cobertura, mix, clientes e ruptura em uma única visão.</p></div><div className="managerHeroActions"><button onClick={()=>setNovoVendedor(true)}>+ Novo vendedor</button><span>GESTOR</span></div></div><div className="kpis managerKpis"><article><span>Vendedores</span><b>{vendedores.length}</b><small>equipe demonstrativa</small></article><article><span>Clientes ativos</span><b>{baseClientes.length}</b><small>carteira carregada</small></article><article><span>Rupturas abertas</span><b>{totalRupturas}</b><small>exigem ação</small></article><article><span>Itens implantados</span><b>{totalMix}</b><small>mix nos clientes</small></article></div><div className="managerTypes"><strong>Clientes por tipo</strong>{["Supermercado","Farmácia","Distribuidor","Loja especializada"].map(t=>{const n=baseClientes.filter(c=>(c.tipoCliente||c.canal)===t).length;return <span key={t}>{t}<b>{n}</b></span>})}</div><div className="managerGrid"><section className="panel"><h3>Desempenho por vendedor</h3>{baseVendedores.map(v=><button className={"sellerRow "+(vendSel.id===v.id?"sellerActive":"")} key={v.id} onClick={()=>setVendSel(v)}><div><strong>{v.nome}</strong><small>{v.zona} · {v.clientes} clientes</small></div><div className="sellerPct"><b>{v.realizado}%</b><span>da meta</span></div></button>)}</section><section className="panel sellerDetail">{vendSel&&<><small>VENDEDOR SELECIONADO</small><h2>{vendSel.nome}</h2><p>{vendSel.zona}</p><div className="sellerStats"><div><span>Meta volume</span><b>{vendSel.meta} un.</b></div><div><span>Carteira</span><b>{vendSel.clientes}</b></div><div><span>Realizado</span><b>{vendSel.realizado}%</b></div></div><div className="bar"><i style={{width:vendSel.realizado+"%"}}/></div><button className="editSeller" onClick={()=>setEditVendedor({...vendSel})}>Gerenciar vendedor e metas</button><h3>Prioridades da gestão</h3><div className="priority">Cobertura de visitas <b>{Math.min(100,vendSel.realizado+7)}%</b></div><div className="priority">Meta de crescimento <b>+{vendSel.metaPercentual??0}%</b></div><div className="priority">Meta de mix por cliente <b>{vendSel.metaMix??0} itens</b></div><div className="priority">Rupturas a tratar <b>{totalRupturas}</b></div><button className="deactivate" onClick={()=>{setBaseVendedores(baseVendedores.filter(v=>v.id!==vendSel.id));setVendSel(baseVendedores.find(v=>v.id!==vendSel.id)||null)}}>Desativar vendedor</button></>}</section></div><div className="panel campaignManager"><div className="title"><div><small>CAMPANHAS E AUTORIZAÇÕES</small><h3>Ações comerciais</h3><p>Cadastre regras simples. Ao atingir a quantidade no pedido, a campanha é aplicada automaticamente.</p></div><button className="primary" onClick={()=>setNovaCampanha(true)}>+ Nova campanha</button></div><div className="campaignGrid simpleCampaigns">{campanhas.map(c=><article key={c.id}><div><strong>{c.nome}</strong><small>{c.tipo} · {c.inicio||"—"} até {c.fim||"—"} · {c.publicoTipo==="Todos"?"Todos":c.publicoTipo+" específico"}</small></div><b>{c.regraTipo==="Produto específico"?c.minimo+" "+c.produto+" → ":c.regraTipo==="Mix de produtos"?c.mixMinimo+" produtos → ":c.regraTipo==="Quantidade + mix"?c.minimo+" un. + "+c.mixMinimo+" produtos → ":c.minimo+" un. → "}{c.brinde}</b><span>{c.status}</span>{c.origemSolicitacaoId&&<div className="campaignScope"><button onClick={()=>setCampanhas(campanhas.map(a=>a.id===c.id?{...a,publicoTipo:"Vendedor",publicoId:String(c.vendedorId)}:a))}>Liberar vendedor</button><button onClick={()=>setCampanhas(campanhas.map(a=>a.id===c.id?{...a,publicoTipo:"Todos",publicoId:""}:a))}>Liberar para todos</button></div>}</article>)}</div>{solicitacoes.some(x=>x.status==="Pendente")&&<div className="approvalList"><h3>Sugestões de campanha do vendedor</h3>{solicitacoes.filter(x=>x.status==="Pendente").map(x=><article key={x.id}><div><strong>{x.nome||"Campanha especial"} · {x.cliente}</strong><small>{x.vendedor} · {x.regraTipo||x.motivo} · {x.minimo?x.minimo+" un.":""} {x.mixMinimo?"+ mix "+x.mixMinimo:""} · {x.brinde||""}</small></div><b>Pendente</b><button onClick={()=>{const campanhaId="sug-"+x.id;setSolicitacoes(solicitacoes.map(a=>a.id===x.id?{...a,status:"Aprovada"}:a));if(x.nome&&!campanhas.some(c=>c.origemSolicitacaoId===x.id))setCampanhas([...campanhas,{...x,id:campanhaId,origemSolicitacaoId:x.id,publicoTipo:"Cliente",publicoId:String(x.clienteId),status:"Ativa"}])}}>Aprovar</button><button className="reject" onClick={()=>setSolicitacoes(solicitacoes.map(a=>a.id===x.id?{...a,status:"Rejeitada"}:a))}>Rejeitar</button></article>)}</div>}</div><div className="panel clientManager"><div className="title"><div><small>CARTEIRA COMERCIAL</small><h3>Gestão de clientes por vendedor</h3><p>Defina quem pode atender cada cliente e transfira a carteira quando necessário.</p></div><button className="primary" onClick={()=>setGestaoClientes(!gestaoClientes)}>{gestaoClientes?"Fechar gestão":"Gerenciar clientes"}</button></div>{gestaoClientes&&<div className="clientAssignList">{baseClientes.map(c=>{const atual=baseVendedores.find(v=>v.id===c.vendedorId);return <article key={c.id}><div><strong>{c.nome}</strong><small>{c.cidade} · {c.canal}</small><em>{c.produtos.length} produtos no mix</em></div><span>{atual?.nome||"Sem vendedor"}</span><button className="metaClientBtn" onClick={()=>setEditClienteMeta({...c})}>Metas</button><select value={c.vendedorId||""} onChange={e=>{const id=+e.target.value||null;setBaseClientes(baseClientes.map(x=>x.id===c.id?{...x,vendedorId:id}:x));if(cliente.id===c.id)setCliente({...cliente,vendedorId:id})}}><option value="">Sem vendedor</option>{baseVendedores.map(v=><option key={v.id} value={v.id}>{v.nome} · {v.zona}</option>)}</select></article>})}</div>}</div><div className="panel territory"><div className="title"><div><small>TERRITÓRIO COMERCIAL</small><h3>Departamentos do Paraguai</h3></div><select value={territorio} onChange={e=>setTerritorio(e.target.value)}><option>Todos</option>{territorios.map(t=><option key={t.nome}>{t.nome}</option>)}</select></div><div className="territoryTable"><div className="territoryHead"><span>Departamento</span><span>Vendedor</span><span>Clientes</span><span>Cobertura</span><span>Rupturas</span><span>Crescimento</span></div>{territorios.filter(t=>territorio==="Todos"||t.nome===territorio).map(t=><article key={t.nome}><strong>{t.nome}</strong><span>{t.vendedor}</span><b>{t.clientes}</b><span>{t.cobertura}%</span><span className={t.rupturas?"danger":""}>{t.rupturas}</span><span>{t.crescimento?t.crescimento+"%":"—"}</span></article>)}</div></div><div className="panel"><h3>Clientes que exigem atenção</h3>{baseClientes.map(c=>{const r=c.produtos.filter(p=>calc(p).status==="Ruptura").length;const pct=c.metaVenda?Math.round((c.vendaRealizada||0)/c.metaVenda*100):0;const atencao=r>0||pct<80;return <button className={"attentionClient "+(atencao?"needs":"")} key={c.id} onClick={()=>{setAbaAtencao("Visão geral");setClienteAtencao(c)}}><div><strong>{c.nome}</strong><small>{c.cidade} · {c.canal}</small></div><span>Venda {c.vendaRealizada||0}/{c.metaVenda||0} un. · {pct}%</span><span>{c.produtos.length}/{c.metaMixCliente||0} mix</span><b>{atencao?"Ver histórico":"Normal"}</b></button>})}</div></section>};
const Diretoria=()=>{const venda=baseClientes.reduce((n,c)=>n+(c.vendaRealizada||0),0),meta=baseClientes.reduce((n,c)=>n+(c.metaVenda||0),0),pct=meta?Math.round(venda/meta*100):0,rupt=baseClientes.reduce((n,c)=>n+c.produtos.filter(p=>calc(p).status==="Ruptura").length,0);return <section className="directorDash"><div className="directorHero"><div><small>DIRETORIA</small><h2>Visão Geral da Empresa</h2><p>Resumo comercial · Setembro 2026</p></div></div><div className="directorKpis"><article><span>Vendas x meta</span><b>{pct}%</b><small>{venda} / {meta} un.</small></article><article><span>Clientes</span><b>{baseClientes.length}</b><small>carteira ativa</small></article><article><span>Rupturas</span><b>{rupt}</b><small>itens em atenção</small></article><article><span>Campanhas</span><b>{campanhas.filter(c=>c.status==="Ativa").length}</b><small>ativas</small></article></div><div className="directorGrid"><article className="directorCard wide"><small>EQUIPE COMERCIAL</small><h3>Performance por vendedor</h3><div className="sellerCompare">{baseVendedores.map(v=><div key={v.id}><strong>{v.nome}</strong><div><i style={{width:Math.min(100,v.realizado||0)+"%"}}/></div><b>{v.realizado||0}%</b></div>)}</div></article><article className="directorCard"><small>SEGMENTAÇÃO</small><h3>Clientes por tipo</h3><div className="attentionMetrics">{["Supermercado","Farmácia","Distribuidor","Loja especializada"].map(t=><span key={t}><b>{baseClientes.filter(c=>(c.tipoCliente||c.canal)===t).length}</b> {t}</span>)}</div></article><article className="directorCard wide"><small>CARTEIRA</small><h3>Clientes x meta</h3><div className="clientBars">{baseClientes.map(c=>{const p=Math.round((c.vendaRealizada||0)/(c.metaVenda||1)*100);return <div key={c.id}><span>{c.nome} · {c.tipoCliente||c.canal||"Sem tipo"}</span><div><i style={{width:Math.min(100,p)+"%"}}/></div><b>{p}%</b></div>})}</div></article><article className="directorCard"><small>ATENÇÃO</small><h3>Operação</h3><div className="attentionMetrics"><span><b>{rupt}</b> rupturas</span><span><b>{baseClientes.filter(c=>c.dias>=7).length}</b> visitas atrasadas</span><span><b>{solicitacoes.filter(x=>x.status==="Pendente").length}</b> aprovações</span></div></article></div></section>};
const Metas=()=>{const totalMeta=baseClientes.reduce((n,c)=>n+(c.metaVenda||c.meta||0),0),totalReal=baseClientes.reduce((n,c)=>n+(c.vendaRealizada||0),0),pct=totalMeta?Math.round(totalReal/totalMeta*100):0,totalMix=baseClientes.reduce((n,c)=>n+(c.metaMixCliente||0),0),mixAtual=baseClientes.reduce((n,c)=>n+c.produtos.length,0);return <section className="goalsPage"><div className="goalHeader"><div><small>DESEMPENHO COMERCIAL</small><h2>Metas do mês</h2><p>Acompanhe volume, crescimento, mix e clientes que precisam de reação.</p></div><b>SET · 2026</b></div><div className="goalKpis"><article><span>Meta de vendas</span><b>{totalMeta} un.</b><small>Realizado {totalReal} un.</small></article><article><span>Atingimento</span><b>{pct}%</b><small>Faltam {Math.max(0,totalMeta-totalReal)} un.</small></article><article><span>Meta de mix</span><b>{totalMix}</b><small>Atual {mixAtual} itens</small></article><article><span>Clientes abaixo de 80%</span><b>{baseClientes.filter(c=>(c.vendaRealizada||0)/(c.metaVenda||1)<.8).length}</b><small>precisam de ação</small></article></div><div className="goalMain"><article className="goalChart"><div className="goalTitle"><div><small>EVOLUÇÃO</small><h3>Realizado x meta mensal</h3></div><strong>{pct}%</strong></div><div className="goalBigBar"><i style={{width:Math.min(100,pct)+"%"}}/></div><div className="goalScale"><span>0</span><span>50%</span><span>Meta 100%</span></div><p>Objetivo de crescimento: <b>12%</b> sobre a base anterior. {pct>=100?"Meta atingida.":`Faltam ${Math.max(0,100-pct)} pontos percentuais.`}</p></article><article className="mixGoal"><small>MIX</small><h3>Implantação de mix</h3><div className="mixNumber"><b>{mixAtual}</b><span>de {totalMix}</span></div><div className="goalBigBar"><i style={{width:Math.min(100,totalMix?Math.round(mixAtual/totalMix*100):0)+"%"}}/></div><p>{totalMix?Math.round(mixAtual/totalMix*100):0}% da meta de mix atingida</p></article></div><div className="goalClients"><div className="goalTitle"><div><small>CARTEIRA</small><h3>Meta por cliente</h3></div><span>Venda · Mix · Situação</span></div>{baseClientes.map(c=>{const cp=c.metaVenda?Math.round((c.vendaRealizada||0)/c.metaVenda*100):0,cm=c.metaMixCliente?Math.round(c.produtos.length/c.metaMixCliente*100):0;return <article key={c.id}><div><strong>{c.nome}</strong><small>{c.tipoCliente||c.canal||"Sem tipo"} · {c.cidade}</small></div><div className="goalMetric"><span>Venda</span><b>{c.vendaRealizada||0}/{c.metaVenda||c.meta||0}</b><i><em style={{width:Math.min(100,cp)+"%"}}/></i><small>{cp}%</small></div><div className="goalMetric"><span>Mix</span><b>{c.produtos.length}/{c.metaMixCliente||0}</b><i><em style={{width:Math.min(100,cm)+"%"}}/></i><small>{cm}%</small></div><strong className={cp>=100?"goalOk":cp>=80?"goalNear":"goalBad"}>{cp>=100?"Meta atingida":cp>=80?"Próximo da meta":"Atenção"}</strong></article>})}</div></section>};
return <main>{sugCampanhaAberta&&<div className="modalBack"><form className="modal" onSubmit={e=>{e.preventDefault();const fd=new FormData(e.currentTarget);setSolicitacoes([{id:Date.now(),cliente:cliente.nome,clienteId:cliente.id,vendedor:vendedorAtual?.nome||"Vendedor",vendedorId:usuarioVendedorId,nome:fd.get("nome"),tipo:fd.get("tipo"),regraTipo:fd.get("regraTipo"),produto:fd.get("produto"),minimo:+fd.get("minimo"),mixMinimo:+fd.get("mixMinimo"),inicio:fd.get("inicio"),fim:fd.get("fim"),brinde:fd.get("brinde"),mecanica:fd.get("mecanica"),status:"Pendente"},...solicitacoes]);setSugCampanhaAberta(false)}}><div className="title"><div><small>SUGESTÃO DO VENDEDOR</small><h2>Propor campanha</h2><p>Será enviada ao gestor para autorização.</p></div><button type="button" className="close" onClick={()=>setSugCampanhaAberta(false)}>×</button></div><label>Nome da ação<input name="nome" required placeholder="Ex.: ação especial Supermercado Central"/></label><div className="formGrid"><label>Tipo<select name="tipo"><option>Sell-in</option><option>Sell-out</option></select></label><label>Regra<select name="regraTipo"><option>Quantidade total</option><option>Produto específico</option><option>Mix de produtos</option><option>Quantidade + mix</option></select></label><label>Início<input name="inicio" type="date" required/></label><label>Fim<input name="fim" type="date" required/></label><label>Quantidade mínima<input name="minimo" type="number" min="0"/></label><label>Mix mínimo<input name="mixMinimo" type="number" min="0"/></label><label>Produto<select name="produto"><option value="">Não se aplica</option>{catalogo.map(p=><option key={p.nome} value={p.nome}>{p.nome}</option>)}</select></label><label>Benefício / brinde<input name="brinde" required placeholder="Ex.: 5 toalhinhas"/></label><label className="fullField">Mecânica / justificativa<input name="mecanica" required placeholder="Explique a proposta para o gestor"/></label></div><div className="modalActions"><button type="button" className="secondary" onClick={()=>setSugCampanhaAberta(false)}>Cancelar</button><button className="primary">Enviar para aprovação</button></div></form></div>}{novaCampanha&&<div className="modalBack"><form className="modal" onSubmit={e=>{e.preventDefault();const fd=new FormData(e.currentTarget);setCampanhas([...campanhas,{id:Date.now(),nome:fd.get("nome"),tipo:fd.get("tipo"),inicio:fd.get("inicio"),fim:fd.get("fim"),publicoTipo:fd.get("publicoTipo"),publicoId:fd.get("publicoId"),regraTipo:fd.get("regraTipo"),produto:fd.get("produto"),mixMinimo:+fd.get("mixMinimo"),mecanica:fd.get("mecanica"),minimo:+fd.get("minimo"),brinde:fd.get("brinde"),status:"Ativa"}]);setNovaCampanha(false)}}><div className="title"><div><small>GESTÃO DE CAMPANHAS</small><h2>Nova campanha</h2></div><button type="button" className="close" onClick={()=>setNovaCampanha(false)}>×</button></div><label>Nome<input name="nome" required/></label><div className="formGrid"><label>Tipo<select name="tipo"><option>Sell-in</option><option>Sell-out</option></select></label><label>Início<input name="inicio" type="date" required/></label><label>Fim<input name="fim" type="date" required/></label><label>Público<select name="publicoTipo"><option>Todos</option><option>Cliente</option><option>Vendedor</option></select><small>Somente o gestor pode liberar uma campanha para todos.</small></label><label>Cliente / vendedor<select name="publicoId"><option value="">Todos / selecione quando necessário</option><optgroup label="Clientes">{baseClientes.map(c=><option key={"c"+c.id} value={c.id}>{c.nome}</option>)}</optgroup><optgroup label="Vendedores">{baseVendedores.map(v=><option key={"v"+v.id} value={v.id}>{v.nome}</option>)}</optgroup></select></label><label>Regra<select name="regraTipo"><option>Quantidade total</option><option>Produto específico</option><option>Mix de produtos</option><option>Quantidade + mix</option></select></label><label>Quantidade mínima<input name="minimo" type="number" min="0" placeholder="24"/></label><label>Mix mínimo<input name="mixMinimo" type="number" min="0" placeholder="3 produtos"/></label><label>Produto específico<select name="produto"><option value="">Não se aplica</option>{catalogo.map(p=><option key={p.nome} value={p.nome}>{p.nome}</option>)}</select></label><label>Benefício / brinde<input name="brinde" placeholder="5 toalhinhas"/></label><label className="fullField">Descrição da mecânica<input name="mecanica" required placeholder="Ex.: compre 12 G + 12 XG e ganhe 5 toalhinhas"/></label></div><div className="modalActions"><button type="button" className="secondary" onClick={()=>setNovaCampanha(false)}>Cancelar</button><button className="primary">Publicar campanha</button></div></form></div>}{historicoCliente&&<div className="modalBack"><div className="modal attentionPro"><div className="attHeader"><div><small>HISTÓRICO COMPLETO</small><h2>{historicoCliente.nome}</h2><p>{historicoCliente.cidade} · {historicoCliente.tipoCliente||historicoCliente.canal||"Sem tipo"}</p></div><button type="button" className="close" onClick={()=>setHistoricoCliente(null)}>×</button></div><div className="historyFullGrid"><section className="attCard"><h3>Últimas vendas e estoques</h3><div className="movement"><header><span>Produto</span><span>Data</span><span>Estoque</span><span>Venda</span></header>{historicoCliente.produtos.flatMap(p=>p.compras.map((h,i)=><div key={p.nome+i}><strong>{p.nome}</strong><span>{h[0]}</span><span>{h[1]}</span><span>{h[2]}</span></div>)).slice(0,18)}</div></section><section className="attCard"><h3>Visitas / atendimentos</h3><div className="visitList">{historicoVisitas.filter(v=>v.cliente===historicoCliente.nome).length?historicoVisitas.filter(v=>v.cliente===historicoCliente.nome).slice(0,6).map((v,i)=><article key={i}><div><strong>{v.data}</strong><small>{v.itens} produtos contados</small></div><b>Concluída</b></article>):<div className="empty">Nenhuma visita registrada nesta sessão.</div>}</div><h3 className="historySub">Resumo comercial</h3><div className="historyNotes"><span><b>{historicoCliente.vendaRealizada||0}</b> vendas no período</span><span><b>{historicoCliente.metaVenda||0}</b> meta de venda</span><span><b>{historicoCliente.produtos.length}</b> produtos no mix</span></div></section></div><div className="attFooter"><button type="button" className="secondary" onClick={()=>setHistoricoCliente(null)}>Fechar</button><button type="button" className="primary" onClick={()=>{setCliente(historicoCliente);setHistoricoCliente(null);setVisita(true)}}>Iniciar atendimento</button></div></div></div>}{clienteAtencao&&<div className="modalBack"><div className="modal attentionPro"><div className="attHeader"><div className="clientIdentity"><div className="storeIcon">▱</div><div><span className="attBadge">CLIENTE EM ATENÇÃO</span><h2>{clienteAtencao.nome}</h2><p>Código: {String(clienteAtencao.id).padStart(4,"0")} <i/> Vendedor: {baseVendedores.find(v=>v.id===clienteAtencao.vendedorId)?.nome||"Sem vendedor"} <i/> Cidade: {clienteAtencao.cidade}</p></div></div><div className="headerButtons"><button type="button" className="editClient" onClick={(e)=>{e.preventDefault();e.stopPropagation();setEditClienteMeta({...clienteAtencao});setClienteAtencao(null)}}>✎ Editar cliente</button><button type="button" className="close" onClick={(e)=>{e.preventDefault();setClienteAtencao(null)}}>×</button></div></div><div className="attKpis"><article><small>Meta de venda</small><b>{clienteAtencao.metaVenda||0}</b><span>Realizado: {clienteAtencao.vendaRealizada||0}</span><div className="progress"><i style={{width:Math.min(100,clienteAtencao.metaVenda?Math.round((clienteAtencao.vendaRealizada||0)/clienteAtencao.metaVenda*100):0)+"%"}}/></div><strong>{clienteAtencao.metaVenda?Math.round((clienteAtencao.vendaRealizada||0)/clienteAtencao.metaVenda*100):0}%</strong></article><article><small>Mix de produtos</small><b>{clienteAtencao.produtos.length} / {clienteAtencao.metaMixCliente||0}</b><span>Produtos implantados</span><div className="progress"><i style={{width:Math.min(100,Math.round(clienteAtencao.produtos.length/(clienteAtencao.metaMixCliente||1)*100))+"%"}}/></div><strong>{Math.min(100,Math.round(clienteAtencao.produtos.length/(clienteAtencao.metaMixCliente||1)*100))}%</strong></article><article className="orderKpi"><small>Último pedido</small><b>{clienteAtencao.produtos[0]?.compras[0]?.[0]||"—"}</b><span>Última movimentação registrada</span></article><article><small>Situação</small><b className="situation">ABAIXO DO ESPERADO</b><span>Ação recomendada</span></article></div><div className="attTabs">{["Visão geral","Histórico por produto","Histórico de vendas","Justificativa e ações","Anotações"].map((t,i)=><button type="button" key={t} className={abaAtencao===t?"active":""} onClick={(e)=>{e.preventDefault();e.stopPropagation();setAbaAtencao(t)}}><span className="tabIcon">{["▥","◇","☷","▣","○"][i]}</span><span>{t}</span></button>)}</div>{abaAtencao==="Visão geral"&&<div className="attGrid"><section><div className="attCard"><h3>Metas do cliente</h3><div className="goalCards"><div><small>Meta de venda</small><b>{clienteAtencao.metaVenda||0} unidades</b></div><div><small>Meta de mix</small><b>{clienteAtencao.metaMixCliente||0} produtos</b></div></div></div><div className="attCard"><h3>Últimas movimentações</h3><div className="movement"><header><span>Produto</span><span>Data</span><span>Estoque</span><span>Venda</span></header>{clienteAtencao.produtos.flatMap(p=>p.compras.slice(0,1).map((h,i)=><div key={p.nome+i}><strong>{p.nome}</strong><span>{h[0]}</span><span>{h[1]}</span><span>{h[2]}</span></div>))}</div></div></section><section><div className="attCard performance"><h3>Desempenho atual</h3><div className="rings"><div className="ring blueRing" style={{"--pct":(clienteAtencao.metaVenda?Math.min(100,Math.round((clienteAtencao.vendaRealizada||0)/clienteAtencao.metaVenda*100)):0)*3.6+"deg"}}><b>{clienteAtencao.metaVenda?Math.round((clienteAtencao.vendaRealizada||0)/clienteAtencao.metaVenda*100):0}%</b></div><div className="ringText"><span>Venda</span><strong>{clienteAtencao.vendaRealizada||0} / {clienteAtencao.metaVenda||0}</strong><small>unidades</small></div><div className="ring greenRing" style={{"--pct":Math.min(100,Math.round(clienteAtencao.produtos.length/(clienteAtencao.metaMixCliente||1)*100))*3.6+"deg"}}><b>{Math.min(100,Math.round(clienteAtencao.produtos.length/(clienteAtencao.metaMixCliente||1)*100))}%</b></div><div className="ringText"><span>Mix</span><strong>{clienteAtencao.produtos.length} / {clienteAtencao.metaMixCliente||0}</strong><small>produtos</small></div><div className="missingMix"><b>↗</b><span>Faltam <strong>{Math.max(0,(clienteAtencao.metaMixCliente||0)-clienteAtencao.produtos.length)} produtos</strong></span><small>para atingir o mix ideal.</small></div></div></div><div className="attCard"><h3>Justificativa do vendedor</h3><textarea value={clienteAtencao.justificativa||""} onChange={e=>setClienteAtencao({...clienteAtencao,justificativa:e.target.value})} placeholder="Por que a venda ficou abaixo do esperado?"/></div><div className="attCard actionCard"><h3>Ação definida</h3><textarea value={clienteAtencao.acao||""} onChange={e=>setClienteAtencao({...clienteAtencao,acao:e.target.value})} placeholder="Qual ação será tomada e quando será o retorno?"/></div></section></div>}{abaAtencao==="Histórico por produto"&&<div className="attSingle"><div className="attCard"><h3>Histórico por produto</h3>{clienteAtencao.produtos.map(p=><div className="productHistoryFull" key={p.nome}><strong>{p.nome}</strong>{p.compras.map((h,i)=><span key={i}>{h[0]} · Estoque {h[1]} · Venda {h[2]}</span>)}</div>)}</div></div>}{abaAtencao==="Histórico de vendas"&&<div className="attSingle"><div className="attCard"><h3>Histórico de vendas</h3><div className="movement"><header><span>Produto</span><span>Data</span><span>Estoque</span><span>Venda</span></header>{clienteAtencao.produtos.flatMap(p=>p.compras.map((h,i)=><div key={p.nome+i}><strong>{p.nome}</strong><span>{h[0]}</span><span>{h[1]}</span><span>{h[2]}</span></div>))}</div></div></div>}{abaAtencao==="Justificativa e ações"&&<div className="attSingle attForms"><div className="attCard"><h3>Justificativa do vendedor</h3><textarea value={clienteAtencao.justificativa||""} onChange={e=>setClienteAtencao({...clienteAtencao,justificativa:e.target.value})}/></div><div className="attCard actionCard"><h3>Ação definida</h3><textarea value={clienteAtencao.acao||""} onChange={e=>setClienteAtencao({...clienteAtencao,acao:e.target.value})}/></div></div>}{abaAtencao==="Visitas"&&<div className="attSingle"><div className="attCard"><h3>Histórico de visitas</h3><div className="visitList">{historicoVisitas.filter(v=>v.cliente===clienteAtencao.nome).length?historicoVisitas.filter(v=>v.cliente===clienteAtencao.nome).map((v,i)=><article key={i}><div><strong>{v.data}</strong><small>{v.itens} produtos contados</small></div><b>Concluída</b></article>):<div className="empty">Ainda não há visitas registradas nesta sessão para este cliente.</div>}</div></div></div>}{abaAtencao==="Anotações"&&<div className="attSingle"><div className="attCard"><h3>Anotações do cliente</h3><textarea className="notesArea" value={clienteAtencao.anotacoes||""} onChange={e=>setClienteAtencao({...clienteAtencao,anotacoes:e.target.value})} placeholder="Registre observações importantes sobre o cliente..."/></div></div>}<div className="attFooter"><button type="button" className="secondary" onClick={(e)=>{e.preventDefault();e.stopPropagation();setAbaAtencao("Visitas")}}>◷ Ver histórico de visitas</button><div><button type="button" className="secondary" onClick={(e)=>{e.preventDefault();setClienteAtencao(null)}}>Fechar</button><button type="button" className="primary" onClick={(e)=>{e.preventDefault();setBaseClientes(baseClientes.map(c=>c.id===clienteAtencao.id?clienteAtencao:c));if(cliente.id===clienteAtencao.id)setCliente(clienteAtencao);setClienteAtencao(null)}}>Salvar acompanhamento</button></div></div></div></div>}{editClienteMeta&&<div className="modalBack"><form className="modal" onSubmit={e=>{e.preventDefault();setBaseClientes(baseClientes.map(c=>c.id===editClienteMeta.id?editClienteMeta:c));if(cliente.id===editClienteMeta.id)setCliente(editClienteMeta);setEditClienteMeta(null)}}><div className="title"><div><small>METAS DO CLIENTE</small><h2>{editClienteMeta.nome}</h2><p>Defina objetivos específicos para este ponto de venda.</p></div><button type="button" className="close" onClick={()=>setEditClienteMeta(null)}>×</button></div><div className="formGrid"><label>Meta de venda (un.)<input type="number" min="0" value={editClienteMeta.metaVenda||0} onChange={e=>setEditClienteMeta({...editClienteMeta,metaVenda:+e.target.value})}/></label><label>Meta de mix (produtos)<input type="number" min="1" value={editClienteMeta.metaMixCliente||1} onChange={e=>setEditClienteMeta({...editClienteMeta,metaMixCliente:+e.target.value})}/></label></div><div className="modalActions"><button type="button" className="secondary" onClick={()=>setEditClienteMeta(null)}>Cancelar</button><button className="primary" type="submit">Salvar metas</button></div></form></div>}{novoVendedor&&<div className="modalBack"><form className="modal" onSubmit={e=>{e.preventDefault();const fd=new FormData(e.currentTarget);const v={id:Date.now(),nome:fd.get("nome"),zona:fd.get("zona"),meta:+fd.get("meta"),metaPercentual:+fd.get("metaPercentual"),metaMix:+fd.get("metaMix"),realizado:0,clientes:0};setBaseVendedores([...baseVendedores,v]);setNovoVendedor(false)}}><div className="title"><div><small>GESTÃO COMERCIAL</small><h2>Novo vendedor</h2><p>Cadastre o vendedor e defina sua meta inicial.</p></div><button type="button" className="close" onClick={()=>setNovoVendedor(false)}>×</button></div><label>Nome<input name="nome" required placeholder="Nome completo"/></label><div className="formGrid"><label>Departamento / território<input name="zona" required placeholder="Ex.: Alto Paraná"/></label><label>Meta mensal (un.)<input name="meta" type="number" min="0" required placeholder="0"/></label><label>Meta de crescimento (%)<input name="metaPercentual" type="number" min="0" step="0.1" required placeholder="12"/></label><label>Meta de mix por cliente<input name="metaMix" type="number" min="1" required placeholder="8"/></label></div><div className="modalActions"><button type="button" className="secondary" onClick={()=>setNovoVendedor(false)}>Cancelar</button><button className="primary" type="submit">Cadastrar vendedor</button></div></form></div>}{editVendedor&&<div className="modalBack"><form className="modal" onSubmit={e=>{e.preventDefault();setBaseVendedores(baseVendedores.map(v=>v.id===editVendedor.id?editVendedor:v));setEditVendedor(null)}}><div className="title"><div><small>GESTÃO COMERCIAL</small><h2>Gerenciar vendedor</h2><p>Edite carteira, território, meta e desempenho.</p></div><button type="button" className="close" onClick={()=>setEditVendedor(null)}>×</button></div><label>Nome do vendedor<input value={editVendedor.nome} onChange={e=>setEditVendedor({...editVendedor,nome:e.target.value})}/></label><div className="formGrid"><label>Departamento / território<input value={editVendedor.zona} onChange={e=>setEditVendedor({...editVendedor,zona:e.target.value})}/></label><label>Clientes na carteira<input type="number" min="0" value={editVendedor.clientes} onChange={e=>setEditVendedor({...editVendedor,clientes:+e.target.value})}/></label><label>Meta de volume (un.)<input type="number" min="0" value={editVendedor.meta} onChange={e=>setEditVendedor({...editVendedor,meta:+e.target.value})}/></label><label>Meta de crescimento (%)<input type="number" min="0" step="0.1" value={editVendedor.metaPercentual??0} onChange={e=>setEditVendedor({...editVendedor,metaPercentual:+e.target.value})}/></label><label>Meta de mix por cliente<input type="number" min="1" value={editVendedor.metaMix??1} onChange={e=>setEditVendedor({...editVendedor,metaMix:+e.target.value})}/></label><label>Realizado (%)<input type="number" min="0" max="200" value={editVendedor.realizado} onChange={e=>setEditVendedor({...editVendedor,realizado:+e.target.value})}/></label></div><div className="modalActions"><button type="button" className="secondary" onClick={()=>setEditVendedor(null)}>Cancelar</button><button type="submit" className="primary">Salvar alterações</button></div></form></div>}{catalogoAberto&&<div className="modalBack"><div className="modal catalogModal"><div className="title"><div><small>CATÁLOGO AUSTEN</small><h2>Implantar novo produto</h2><p>O vendedor tem acesso ao cadastro completo e pode ampliar o mix deste cliente.</p></div><button className="close" onClick={()=>setCatalogoAberto(false)}>×</button></div><input className="catalogSearch" placeholder="Buscar produto, marca ou linha..." value={buscaProduto} onChange={e=>setBuscaProduto(e.target.value)}/><div className="catalogList">{catalogo.filter(p=>(p.nome+" "+p.marca+" "+p.linha).toLowerCase().includes(buscaProduto.toLowerCase())).map(p=>{const ativo=cliente.produtos.some(x=>x.nome===p.nome);return <article key={p.nome}><div><strong>{p.nome}</strong><small>{p.marca} · {p.linha}</small></div>{ativo?<div className="catalogActions"><span>Já no mix</span><button onClick={()=>removerProduto(p.nome)}>Remover</button></div>:<button className="primary" onClick={()=>implantarProduto(p)}>+ Implantar</button>}</article>})}</div></div></div>}{cadastro&&<div className="modalBack"><form className="modal" onSubmit={salvarCliente}><div className="title"><div><small>NOVO CLIENTE</small><h2>Cadastrar cliente</h2></div><button type="button" className="close" onClick={()=>setCadastro(false)}>×</button></div><label>Nome / Razão social<input value={novo.nome} onChange={e=>setNovo({...novo,nome:e.target.value})} placeholder="Ex.: Supermercado América" required/></label><div className="formGrid"><label>Cidade<input value={novo.cidade} onChange={e=>setNovo({...novo,cidade:e.target.value})} placeholder="Ciudad del Este" required/></label><label>Tipo de cliente<select value={novo.tipoCliente} onChange={e=>setNovo({...novo,tipoCliente:e.target.value,canal:e.target.value})}><option>Farmácia</option><option>Distribuidor</option><option>Supermercado</option><option>Loja especializada</option></select></label><label>Responsável<input value={novo.responsavel} onChange={e=>setNovo({...novo,responsavel:e.target.value})} placeholder="Nome do contato"/></label><label>Telefone / WhatsApp<input value={novo.telefone} onChange={e=>setNovo({...novo,telefone:e.target.value})} placeholder="+595 ..."/></label></div><div className="modalActions"><button type="button" className="secondary" onClick={()=>setCadastro(false)}>Cancelar</button><button type="submit" className="primary">Salvar cliente</button></div></form></div>}<header><div><small>AUSTEN · GRUPO EUROFRAL</small><h1>Austen Comercial</h1><p>Execução de campo, estoque e reposição inteligente.</p></div><div className="profileSwitch"><button className={perfil==="vendedor"?"on":""} onClick={()=>{setPerfil("vendedor");setAba("Visão geral");const c=baseClientes.find(x=>x.vendedorId===usuarioVendedorId);if(c)setCliente(c)}}>Vendedor</button><button className={perfil==="gestor"?"on":""} onClick={()=>{setPerfil("gestor");setAba("Gestão")}}>Gestor</button><button className={perfil==="diretoria"?"on":""} onClick={()=>{setPerfil("diretoria");setAba("Diretoria")}}>Diretoria</button></div></header>{aba==="Visão geral"&&<Dashboard/>}{aba==="Clientes"&&<ClienteDetalhe/>}{aba==="Visitas"&&<Visitas/>}{aba==="Pedidos"&&<Pedidos/>}{aba==="Metas"&&<Metas/>}{aba==="Gestão"&&perfil==="gestor"&&<Gestor/>}{aba==="Diretoria"&&perfil==="diretoria"&&<Diretoria/>}<nav>{(perfil==="diretoria"?["Diretoria"]:perfil==="gestor"?["Visão geral","Clientes","Visitas","Pedidos","Metas","Gestão"]:["Visão geral","Clientes","Visitas","Pedidos","Metas"]).map(n=><button key={n} className={aba===n?"sel":""} onClick={()=>setAba(n)}>{n}</button>)}</nav></main>}